corpus_block("test-geom-smooth.R: default smoothing methods for small and large data sets work", {
  withr::local_options(warnPartialMatchArgs = FALSE)
  skip_on_cran()
  set.seed(6531)
  x <- rnorm(10)
  df <- data_frame(
      x = x,
      y = x^2 + 0.5 * rnorm(10)
    )
  m <- loess(y ~ x, data = df, span = 0.75)
  range <- range(df$x, na.rm = TRUE)
  xseq <- seq(range[1], range[2], length.out = 80)
  out <- predict(m, data_frame(x = xseq))
  .plot("test-geom-smooth.R: default smoothing methods for small and large data sets work #1", p <- ggplot(df, aes(x, y)) + geom_smooth())
  x <- rnorm(1001)
  df <- data_frame(
      x = x,
      y = x^2 + 0.5 * rnorm(1001)
    )
  skip_if_not_installed("mgcv")
  m <- mgcv::gam(y ~ s(x, bs = "cs"), data = df, method = "REML")
  range <- range(df$x, na.rm = TRUE)
  xseq <- seq(range[1], range[2], length.out = 80)
  out <- predict(m, data_frame(x = xseq))
  .plot("test-geom-smooth.R: default smoothing methods for small and large data sets work #2", p <- ggplot(df, aes(x, y)) + geom_smooth())
  .plot("test-geom-smooth.R: default smoothing methods for small and large data sets work #3", p <- ggplot(df, aes(x, y)) + geom_smooth(method = "auto"))
})

